begin;
create temporary table evidence_assertions(label text,passed boolean,detail text);
alter table evidence_assertions enable row level security;
create policy temporary_assertions on evidence_assertions for all to anon,authenticated using(true) with check(true);
grant select,insert on evidence_assertions to authenticated,anon;
do $$begin execute format('grant usage on schema %I to authenticated,anon',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end$$;
create function pg_temp.ok(value boolean,label text) returns boolean language plpgsql as $$begin insert into pg_temp.evidence_assertions values(label,coalesce(value,false),null);return value;end$$;
create function pg_temp.denied(command text,expected text,label text) returns boolean language plpgsql as $$declare code text:='00000';detail text;begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate,detail=message_text;end;insert into pg_temp.evidence_assertions values(label,code=expected,case when code<>expected then code||':'||coalesce(detail,'No error')end);return code=expected;end$$;
insert into auth.users(id,email) values('a9200000-0000-0000-0000-000000000001','evidence-c1@example.test'),('a9200000-0000-0000-0000-000000000002','evidence-c2@example.test'),('a9200000-0000-0000-0000-000000000003','evidence-staff@example.test');
insert into vb_private.staff_members(user_id) values('a9200000-0000-0000-0000-000000000003');
insert into public.vb_clients(id,name,client_type,contact_name,portal_enabled) values('b9200000-0000-0000-0000-000000000001','Evidence fixture one','business','Fictional',true),('b9200000-0000-0000-0000-000000000002','Evidence fixture two','business','Fictional',true);
insert into public.vb_marks(id,client_id,name,mark_type,status) values('c9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001','EVIDENCE ONE','word','not_filed'),('c9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000002','EVIDENCE TWO','word','not_filed');
insert into vb_private.client_memberships(client_id,user_id) values('b9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001'),('b9200000-0000-0000-0000-000000000002','a9200000-0000-0000-0000-000000000002');
select pg_temp.ok((select not public and file_size_limit=10485760 and allowed_mime_types=array['image/png','image/jpeg'] from storage.buckets where id='vb-evidence'),'Private image-only 10 MB bucket');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select public.vb_reserve_evidence('e9200000-0000-0000-0000-000000000001','b9200000-0000-0000-0000-000000000001','c9200000-0000-0000-0000-000000000001',jsonb_build_object('kind','webpage','capturedOn',current_date,'sourceUrl','https://example.test','filename','fixture.png','mimeType','image/png','byteSize',68,'sha256',repeat('a',64)));
select pg_temp.ok((select count(*)=0 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000001'),'Pending uploads hidden');
select pg_temp.denied($$select public.vb_finish_evidence('e9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001')$$,'42501','Client cannot finalize unvalidated images');
select pg_temp.denied($$insert into storage.objects(bucket_id,name)values('vb-evidence','bypass.png')$$,'42501','Client cannot bypass validating upload backend');
select pg_temp.denied($$select public.vb_reserve_evidence('e9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000002','c9200000-0000-0000-0000-000000000002','{}')$$,'42501','Cross-client upload denied');
select pg_temp.denied($$select public.vb_reserve_evidence('e9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000001','c9200000-0000-0000-0000-000000000002','{}')$$,'42501','Wrong mark ownership denied');
select pg_temp.denied($$update public.vb_evidence set notes='changed'$$,'42501','Original records cannot be overwritten');
select pg_temp.denied($$delete from public.vb_evidence$$,'42501','Original history cannot be deleted');
reset role;
select pg_temp.denied($$select public.vb_finish_evidence('e9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001')$$,'22023','Missing image cannot complete');
insert into storage.objects(bucket_id,name,metadata)values('vb-evidence','b9200000-0000-0000-0000-000000000001/c9200000-0000-0000-0000-000000000001/e9200000-0000-0000-0000-000000000001.png','{"size":68,"mimetype":"image/png"}');
select public.vb_finish_evidence('e9200000-0000-0000-0000-000000000001','a9200000-0000-0000-0000-000000000001');
set local role authenticated;
select pg_temp.ok((select count(*)=1 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000001'),'Client reads own completed evidence');
select pg_temp.ok((select count(*)=1 from storage.objects where bucket_id='vb-evidence' and name like 'b9200000%'),'Client reads own image');
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_evidence),'Second client cannot read first evidence');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='vb-evidence'),'Second client cannot read first image');
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_evidence),'Attorney without MFA cannot read evidence');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='vb-evidence'),'Attorney without MFA cannot read images');
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal2"}',true);
select pg_temp.ok((select count(*)=1 from public.vb_evidence where id='e9200000-0000-0000-0000-000000000001'),'MFA attorney reads evidence');
select pg_temp.ok((select count(*)=1 from storage.objects where bucket_id='vb-evidence' and name like 'b9200000%'),'MFA attorney reads image');
select pg_temp.denied($$select public.vb_reserve_evidence('e9200000-0000-0000-0000-000000000002','b9200000-0000-0000-0000-000000000001','c9200000-0000-0000-0000-000000000001','{}')$$,'42501','Attorney cannot upload as a client');
reset role;
update public.vb_clients set portal_enabled=false where id='b9200000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9200000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.ok((select count(*)=0 from public.vb_evidence),'Disabled client evidence access revoked');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='vb-evidence'),'Disabled client image access revoked');
reset role;
set local role anon;
select pg_temp.denied($$select * from public.vb_evidence$$,'42501','Signed-out record reads denied');
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='vb-evidence'),'Signed-out image reads denied');
reset role;
select jsonb_build_object('executed',count(*),'all_passed',bool_and(passed),'assertions',jsonb_agg(to_jsonb(a)))as evidence_test_results from pg_temp.evidence_assertions a;
rollback;
